"""Démarches complémentaires : chaque bloc existant est conservé, six remplacements par notion."""
SLOTS=(1,3,6,8,13,19)
USED={n:0 for n in IDS}
def N(n,title,diff,intro,rows,note):
    slot=SLOTS[USED[n]] if n!=136 else len(RECORDS[n]); USED[n]+=1
    eid=RECORDS[n][slot]['id'] if n!=136 else 'nouveau-'+str(USED[n])
    qs=[Q(q,m,s,a) for q,m,s,a in rows]
    ex=dict(id=eid,titre=title,difficulte=diff,introduction=intro,questions=qs,note=note)
    if n==136: RECORDS[n].append(ex)
    else: RECORDS[n][slot]=ex
def step(title,text): return [(title,text)]

N(132,'Découverte - Fractions - Lire des quarts sur une demi-droite','easy',r'Une unité mesure 4 cm. Tracer une demi-droite graduée de 0 à 2 et la partager en quarts.',[
 (r'Placer $A$ d’abscisse $\frac34$ et $B$ d’abscisse $\frac74$.','Compter les quarts depuis l’origine.', [('Construire la graduation',r'Placer 0, 1 et 2 à 0 cm, 4 cm et 8 cm. Chaque quart mesure 1 cm.'),('Placer les points',r'A se place à 3 cm de 0 ; B à 7 cm de 0.\n\n[IMAGE_1]')],r'$A\left(\frac34\right)$ et $B\left(\frac74\right)$.'),
 (r'Écrire $\frac74$ comme somme d’un entier et d’une fraction inférieure à 1.','Regrouper quatre quarts en une unité.',step('Décomposer sept quarts',M(r'\frac74=\frac44+\frac34=1+\frac34')),r'$1+\frac34$.'),
 ('Quelle est la distance de A à B, en unités de la graduation ?','Compter les intervalles entre les points.',step('Compter quatre quarts',M(r'\frac74-\frac34=\frac44=1')),r'Une unité, soit 4 cm sur le dessin.')],r'Une fraction est une abscisse : on compte depuis 0, en respectant la longueur choisie pour l’unité.')
N(132,'Découverte - Fractions - Compléter des multiplications','easy',r'On cherche chaque nombre manquant, sans l’arrondir.',[
 (r'Compléter $5\times\square=3$.','Le quotient de 3 par 5 est le nombre qui, multiplié par 5, donne 3.',step('Vérifier par multiplication',M(r'5\times\frac35=3')),r'$\square=\frac35$.'),
 (r'Compléter $4\times\square=9$.','Le quotient peut être supérieur à 1.',step('Écrire le quotient exact',M(r'4\times\frac94=9')),r'$\square=\frac94$.'),
 (r'Pour la question 1, $0{,}6$ convient-il ? Et pour la question 2, $2{,}25$ ?','Contrôler les écritures décimales par le produit.',step('Contrôler les deux propositions',chain(r'5\times0{,}6&=3',r'4\times2{,}25&=9')),r'Oui, les deux écritures décimales sont exactes.')],r'Une égalité à trou se vérifie en remplaçant le trou par la valeur proposée.')
N(132,'Découverte - Fractions - Entier, décimal ou non décimal ?','easy',r'On étudie $\frac{12}{4}$, $\frac58$ et $\frac23$.',[
 (r'La fraction $\frac{12}{4}$ représente-t-elle un entier ?','Effectuer le quotient exact.',step('Diviser',M(r'12\div4=3')),r'Oui : 3.'),
 (r'Donner l’écriture décimale exacte de $\frac58$.','Partager 5 en 8 parts égales.',step('Effectuer la division',M(r'5\div8=0{,}625')),r'$0{,}625$.'),
 (r'$0{,}666$ est-il exactement égal à $\frac23$ ?','Vérifier le nombre proposé par la multiplication qui définit le quotient.', [('Multiplier par le dénominateur',M(r'3\times0{,}666=1{,}998')),('Conclure',r'Le produit est différent de 2. La division de 2 par 3 ne s’arrête pas : la fraction n’a pas d’écriture décimale finie.')],r'Non : $0{,}666$ est une approximation, et $\frac23$ est la valeur exacte.')],r'Une fraction peut représenter un entier, un décimal non entier ou un nombre non décimal.')
N(132,'Entraînement - Fractions - Partager un segment avec un guide-âne','medium',r'On dispose d’un segment de 3 cm et d’un réseau de droites parallèles régulièrement espacées. On veut partager le segment en 7 parties égales.',[
 ('Comment positionner les extrémités sur le réseau ?','Intercepter exactement sept bandes égales entre les parallèles.',step('Positionner le segment',r'Placer la première extrémité sur une parallèle et faire pivoter le segment pour que l’autre soit sur la huitième parallèle : on traverse sept intervalles.\n\n[IMAGE_1]'),'Les extrémités doivent intercepter sept intervalles du réseau.'),
 ('Quelle est la longueur exacte d’une partie ?','Diviser la longueur totale par le nombre de parties égales.',step('Écrire le quotient',M(r'3\div7=\frac37')),r'$\frac37$ cm.'),
 ('Pourquoi ne doit-on pas utiliser 0,43 cm comme longueur exacte d’une partie ?','Vérifier si sept fois cette valeur reconstitue 3 cm.',step('Contrôler l’approximation',M(r'7\times0{,}43=3{,}01')),r'Les sept parties totaliseraient 3,01 cm : 0,43 cm est seulement une approximation.')],r'Sept parts correspondent à sept intervalles, donc à huit parallèles rencontrées, extrémités comprises.')
N(132,'Entraînement - Fractions - Encadrer un quotient sans division','medium',r'On considère $\frac{17}{5}$.',[
 ('Entre quels entiers consécutifs se trouve ce nombre ?','Encadrer le numérateur entre deux multiples consécutifs du dénominateur.',step('Encadrer par des multiples de 5',M(r'3\times5=15<17<20=4\times5')),r'$3<\frac{17}{5}<4$.'),
 ('Donner une écriture avec un entier et une fraction inférieure à 1.','Séparer les groupes complets de cinq et le reste.',step('Décomposer le numérateur',M(r'\frac{17}{5}=\frac{15+2}{5}=3+\frac25')),r'$3+\frac25$.'),
 ('Donner l’écriture décimale exacte et vérifier l’encadrement.','Convertir les cinquièmes en dixièmes.',step('Exprimer deux cinquièmes en dixièmes',M(r'\frac25=\frac4{10}=0{,}4')),r'$3{,}4$, bien compris entre 3 et 4.')],r'Encadrer un quotient peut se faire avant toute division : les multiples du dénominateur suffisent.')
N(132,'Problème - Fractions - Deux partages, une même longueur','hard',r'Un atelier partage 3 m de ruban entre 4 enfants. Un autre partage 6 m entre 8 enfants. Les rubans sont identiques et les partages équitables.',[
 ('Les enfants reçoivent-ils la même longueur dans les deux ateliers ?','Comparer les quotients sans se fier aux seuls totaux.',step('Comparer les parts',M(r'\frac68=\frac{6\div2}{8\div2}=\frac34')),r'Oui : chacun reçoit $\frac34$ m.'),
 ('On ajoute un enfant au premier groupe, sans ajouter de ruban. Quelle est la nouvelle part ?','Le total reste le même mais le nombre de parts augmente.',step('Calculer le nouveau quotient',M(r'3\div5=\frac35=0{,}6')),r'$\frac35$ m, soit 0,6 m.'),
 ('Combien de ruban faut-il ajouter pour que cinq enfants reçoivent chacun la part initiale ?','Calculer le total nécessaire puis retirer les 3 m disponibles.', [('Calculer la longueur nécessaire',M(r'5\times\frac34=\frac{15}4=3{,}75')),('Calculer le manque',M(r'3{,}75-3=0{,}75'))],r'Il faut ajouter 0,75 m.')],r'Multiplier les deux termes d’un quotient par le même nombre conserve la part ; ajouter une personne seule la modifie.')

N(134,'Découverte - Proportionnalité - Reconnaître un prix proportionnel','easy',r'Chez A, 2 kg de pommes coûtent 5 € et 6 kg coûtent 15 €. Chez B, 2 kg coûtent 5 € et 6 kg coûtent 13 €.',[
 ('Les deux prix de A sont-ils compatibles avec un prix proportionnel à la masse ?','Comparer le même changement de masse et de prix.',step('Tester le triplement',M(r'6=3\times2\qquad15=3\times5')),'Oui : les deux prix sont compatibles avec un prix de 2,50 € par kilogramme.'),
 ('Les prix de B sont-ils proportionnels à la masse ?','Un triplement de masse doit tripler le prix.',step('Comparer le prix attendu au prix annoncé',r'Le triple de 5 € est 15 €, alors que le prix annoncé est 13 €.'),'Non : 6 kg devraient coûter 15 €.'),
 ('Chez A, quel prix pour 4 kg, si la même tarification s’applique ?','Doubler la masse et le prix de la donnée à 2 kg.',step('Doubler les deux grandeurs',M(r'2\times5=10')),r'10 €.')],r'Une seule incompatibilité suffit à montrer que des grandeurs ne sont pas proportionnelles.')
N(134,'Découverte - Proportionnalité - Additionner et partager des achats','easy',r'Le prix des croissants est proportionnel à leur nombre. Quatre croissants coûtent 3,60 €.',[
 ('Quel prix pour douze croissants ?','Tripler les deux quantités.',step('Utiliser trois lots de quatre',M(r'3\times3{,}60=10{,}80')),r'10,80 €.'),
 ('Quel prix pour deux croissants ?','Partager les deux quantités par deux.',step('Prendre un demi-lot',M(r'3{,}60\div2=1{,}80')),r'1,80 €.'),
 ('Quel prix pour six croissants sans calculer le prix d’un seul ?','Additionner les prix de deux achats connus.',step('Assembler un lot de quatre et un lot de deux',M(r'3{,}60+1{,}80=5{,}40')),r'5,40 €.')],r'En proportionnalité, on peut multiplier, diviser et additionner des quantités correspondantes.')
N(134,'Découverte - Proportionnalité - Retrouver une quantité depuis le prix','easy',r'Au même tarif, 5 cahiers coûtent 7,50 €.',[
 ('Quel est le prix d’un cahier ?','Revenir à une unité.',step('Partager le prix de cinq cahiers',M(r'7{,}50\div5=1{,}50')),r'1,50 €.'),
 ('Combien coûtent huit cahiers ?','Multiplier le prix unitaire par le nombre de cahiers.',step('Former huit unités',M(r'8\times1{,}50=12')),r'12 €.'),
 ('Combien de cahiers peut-on acheter avec 18 € ?','Chercher combien de prix unitaires composent le budget.',step('Vérifier par multiplication',M(r'12\times1{,}50=18')),r'12 cahiers.')],r'Le retour à l’unité permet de calculer aussi bien un prix qu’une quantité.')
N(134,'Entraînement - Échelles - Une carte et des unités différentes','medium',r'Sur une carte, 1 cm représente 50 m dans la réalité.',[
 ('Quelle distance réelle représente un segment de 6,5 cm ?','Multiplier la longueur de carte par la distance réelle d’un centimètre.',step('Calculer la distance réelle',M(r'6{,}5\times50=325')),r'325 m.'),
 ('Quelle longueur de carte représente 400 m ?','Chercher le nombre de distances de 50 m.',step('Diviser par la distance représentée par un centimètre',M(r'400\div50=8')),r'8 cm.'),
 ('Quelle est l’échelle écrite sous la forme 1/… ?','Exprimer les deux longueurs dans la même unité.', [('Convertir les mètres en centimètres',M(r'50\ \mathrm{m}=5\,000\ \mathrm{cm}')),('Comparer les mêmes unités',r'1 cm de carte correspond à 5 000 cm réels.')],r'Échelle 1/5 000.')],r'Un centimètre pour 50 mètres ne donne pas une échelle 1/50 : il faut d’abord unifier les unités.')
N(134,'Entraînement - Proportionnalité - Un forfait change le raisonnement','medium',r'Une livraison coûte 4 € fixes, auxquels on ajoute 2 € par colis.',[
 ('Calculer le prix pour un colis puis pour deux colis.','Ajouter le forfait une seule fois à chaque livraison.',step('Calculer les deux prix',chain(r'4+2&=6',r'4+2\times2&=8')),r'6 € pour un colis ; 8 € pour deux.'),
 ('Le prix total est-il proportionnel au nombre de colis ?','Tester si doubler les colis double le prix.',step('Comparer au double du premier prix',M(r'2\times6=12\ne8')),'Non : 8 € n’est pas le double de 6 €.'),
 ('Sans le forfait, quel serait le prix de cinq colis ?','Ne garder que le prix répété par colis.',step('Calculer la part variable',M(r'5\times2=10')),r'10 € ; cette part seule est proportionnelle au nombre de colis.')],r'Une somme fixe ajoutée empêche généralement la proportionnalité, même si chaque colis a le même prix.')
N(134,'Problème - Proportionnalité - Adapter puis comparer deux recettes','hard',r'Pour 4 personnes, la recette A demande 240 g de farine ; pour 3 personnes, la recette B demande 210 g. On adapte chaque recette proportionnellement.',[
 ('Quelle masse demande chaque recette pour 6 personnes ?','Comparer les recettes pour un même effectif.', [('Trouver les masses par personne',chain(r'240\div4&=60',r'210\div3&=70')),('Adapter à six personnes',chain(r'6\times60&=360',r'6\times70&=420'))],r'A : 360 g ; B : 420 g.'),
 ('Avec 800 g, peut-on préparer les deux recettes pour 6 personnes chacune ?','Additionner les besoins, puis comparer au stock.',step('Calculer le besoin total et le reste',chain(r'360+420&=780',r'800-780&=20')),r'Oui ; il reste 20 g.'),
 ('Avec 800 g, combien de personnes au maximum peut-on servir avec la recette B seule ?','Tester deux effectifs entiers consécutifs.',step('Vérifier la limite',M(r'11\times70=770\le800<840=12\times70')),r'11 personnes au maximum.')],r'Pour comparer deux recettes, ramener leurs quantités au même nombre de personnes.')

